private final ConcurrentHashMap<String, Instant> seen = new ConcurrentHashMap<>();

boolean claim(Message m) {                 // null => we won, non-null => duplicate
    return seen.putIfAbsent(m.idempotencyKey(), Instant.now().plus(REDELIVERY_WINDOW)) == null;
}

void onMessage(Message m) {
    if (!claim(m)) { channel.ack(m); return; }   // duplicate: absorb
    handler.applyEffects(m);
    channel.ack(m);
}

