@Transactional
public void handle(OrderMessage msg) {
    try {
        inboxRepo.saveAndFlush(new InboxEntry(msg.idempotencyKey()));  // UNIQUE(key)
    } catch (DataIntegrityViolationException duplicate) {
        return;                              // already processed: absorb
    }
    orderRepo.save(Order.from(msg));         // same transaction
}
